#include "stdafx.h"

// =============================================================================
//  LocalizationFR.cpp    The Hell 4 -- French overlay
//  LANG_FR = 6. Latin script, CP1252 with REAL ACCENTS.
//
//  French text is written with real accents (a-grave, e-acute, c-cedilla, the
//  circumflexes and diaereses, etc.) as raw CP1252 bytes. It reuses the
//  Portuguese font / codepage path (dataseg.cpp Codepage_Portuguese and the
//  FontIndex*_Portuguese tables): the MID and BIG in-game fonts carry those
//  accent glyphs, while the SMALL font folds them to the base letter (readable).
//  The only French glyphs the PT font lacks are the oe/OE ligature and
//  y-diaeresis; write those folded to "oe" / "OE" / "y".
//
//  META-MENU text (main menu, Choose Class dialog, etc. in Hell.cpp) uses the
//  DiabloFont atlas, which has NO accents, so that text is ASCII-folded there
//  -- NOT in this file. This file feeds the in-game overlay lookups only.
//
//  ---- STATUS -------------------------------------------------------------
//  Scaffold. All overlay tables hold a lone placeholder => their getters report
//  0 rows => those categories fall back to English until filled (baby-steps,
//  like the PT/IT passes). The dedicated FR_* functions likewise fall back to
//  English (return nullptr) until translated per-category. Keys must byte-exactly
//  match the English source literal (case, trailing spaces, colons, %i/%s/%u).
//
//  English source and the RU/ID/PT/ES/IT tables are never touched from this file.
// =============================================================================

struct UiStr  { const char* en; const char* fr; }; // .fr column holds the FR text
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

