// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* FR_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(FR_Ui);           return FR_Ui;
		case OVL_MENU:          *n = countRows(FR_Menu);         return FR_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(FR_UniqueItem);   return FR_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(FR_AffixPrefix);  return FR_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(FR_AffixSuffix);  return FR_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(FR_BaseItem);     return FR_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(FR_BaseName2);    return FR_BaseName2;
		case OVL_ELEMENT:       *n = countRows(FR_Element);      return FR_Element;
		case OVL_SPICIES:       *n = countRows(FR_Spicies);      return FR_Spicies;
		case OVL_ICEAGE:        *n = countRows(FR_IceAge);       return FR_IceAge;
		case OVL_SPELL:         *n = countRows(FR_Spell);        return FR_Spell;
		case OVL_SPELL_NOM:     *n = countRows(FR_SpellNom);     return FR_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(FR_PerkName);     return FR_PerkName;
		case OVL_PERK_DESC:     *n = countRows(FR_PerkDesc);     return FR_PerkDesc;
		case OVL_WARP:          *n = countRows(FR_Warp);         return FR_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* FR_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(FR_Speech);     return FR_Speech;
		case OVL_ONSCREEN:  *n = countRows(FR_OnScreen);   return FR_OnScreen;
		case OVL_QUEST:     *n = countRows(FR_Quest);      return FR_Quest;
	}
	*n = 0; return 0;
}

